<script>
 import {onDestroy} from 'svelte';
 import Explorer from './Explorer.svelte';
 import Brief from './Brief.svelte';
 import SevenDays from './SevenDays.svelte';
 import Meteorology from './Meteorology.svelte';
 import {sourceHealth} from './visuals.mjs';
 import {diagnostics,verticalProfile,windowSummary,predictability,windComponents} from './diagnostics.mjs';
 import {MODELS,HOUR,finite,normalize,describe,at,value,fieldFor,format,timeLabel,nearestIndex,derived,briefing,compare,requirements} from './engine.mjs';
 export let location=null, timestamp=Date.now(), load, onLocation=()=>{}, onTime=()=>{}, demo=false,mapModel=null,placeName='',winterComponent=null;
 let model='mblue',data=null,busy=false,error='',request=0,view='Brief',search='',group='All',selected=null,settings=false,detailsOpen=false,compareBusy=false,comparisons=[],comparisonErrors=[],compareRequest=0;
 let prefs={temp:'C',wind:'kt',local:false,winterUnits:'metric'},pins=['temperature','dewPoint','wind','windGust','pressure','precipAmount'],favorites=[],thresholds={gust:15,rain:2};
 try{const saved=JSON.parse(localStorage.getItem('weatherscope-v1')||'{}');prefs={...prefs,...saved.prefs};if(MODELS[saved.model])model=saved.model;if(saved.thresholds&&finite(saved.thresholds.gust)&&saved.thresholds.gust>0&&finite(saved.thresholds.rain)&&saved.thresholds.rain>0)thresholds=saved.thresholds;if(Array.isArray(saved.pins))pins=saved.pins.filter(v=>typeof v==='string').slice(0,12);if(Array.isArray(saved.favorites))favorites=saved.favorites.filter(p=>finite(p.lat)&&finite(p.lon)&&Math.abs(p.lat)<=90&&Math.abs(p.lon)<=180).slice(0,30);}catch{}

 try{const old=JSON.parse(localStorage.getItem('snowline:favourites:v1')||'[]');if(!JSON.parse(localStorage.getItem('weatherscope-v1')||'{}').winterImported&&Array.isArray(old))for(const p of old){const lat=Number(p.lat),lon=Number(p.lon);if(finite(lat)&&finite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180&&!favorites.some(f=>Math.abs(f.lat-lat)<.0001&&Math.abs(f.lon-lon)<.0001)){favorites=[...favorites,{lat,lon,name:[p.primary,p.secondary].filter(Boolean).join(', ')}].slice(0,30);}}}catch{}
 const save=()=>{try{localStorage.setItem('weatherscope-v1',JSON.stringify({prefs,pins,favorites,model,thresholds,winterImported:true}));}catch{}};
 save();
 $: if(location&&model) refresh(location,model);
 async function refresh(loc,source,force=false){const token=++request;compareRequest++;compareBusy=false;busy=true;error='';data=null;selected=null;comparisons=[];comparisonErrors=[];try{const result=await load(source,loc,force);if(token===request)data=result;}catch(e){if(token===request)error=e?.message||'Forecast unavailable. Try again.';}finally{if(token===request)busy=false;}}
 onDestroy(()=>{request++;compareRequest++;});
 $: index=data?nearestIndex(data.ts,timestamp):-1;
 $: valid=index>=0?data.ts[index]:timestamp;
 $: extra=data?[...derived(data,valid),...diagnostics(data,valid)]:[];
 $: fields=data?[...data.fields,...extra]:[];
 $: groups=['All',...new Set(fields.map(f=>f.group))];
 $: filtered=fields.filter(f=>(group==='All'||f.group===group)&&`${f.label} ${f.key} ${f.section}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>Number(pins.includes(b.key))-Number(pins.includes(a.key)));
 $: served=data?(MODELS[data.model]||data.model):MODELS[model];
 $: selectedField=selected?fields.find(f=>f.id===selected):null;
 $: profile=data?[...new Set(data.fields.map(f=>f.key.match(/^temp-(\d+)h$/)?.[1]).filter(Boolean))].map(Number).sort((a,b)=>b-a):[];
 $: health=data?sourceHealth(data,valid):null;
 $: profileRows=data?verticalProfile(data,valid):[];
 $: hodo=profileRows.filter(p=>p.belowGround===false).map(p=>({...p,...windComponents(p.wind,p.dir)})).filter(p=>finite(p.u)&&finite(p.v));
 $: hodoScale=Math.max(20,...hodo.map(p=>Math.max(Math.abs(p.u),Math.abs(p.v))))*1.1;
 $: coverage=requirements.map(([label,key,note])=>({label,key,note,available:!!(key&&fields.some(f=>f.key===key&&finite(at(f,valid))))}));
 function pin(key){pins=pins.includes(key)?pins.filter(k=>k!==key):[...pins.slice(-11),key];save();}
 function inspect(key){selected=(fields.find(f=>f.key===key)||{}).id||null;view='Parameters';detailsOpen=true;search=key;group='All';}
 function chooseTime(t){timestamp=t;onTime(t);}
 function shortcut(hours){const t=Date.now()+hours*HOUR;const i=data?nearestIndex(data.ts,t,Infinity): -1;if(i>=0)chooseTime(data.ts[i]);}
 $: isFavorite=!!location&&favorites.some(p=>Math.abs(p.lat-location.lat)<0.0001&&Math.abs(p.lon-location.lon)<0.0001);
 function switchView(name){if(!name)return;view=name;if(name==='Compare'&&!comparisons.length&&!compareBusy&&data)compareModels();}
 function favorite(){if(!location)return;const same=p=>Math.abs(p.lat-location.lat)<0.0001&&Math.abs(p.lon-location.lon)<0.0001;favorites=favorites.some(same)?favorites.filter(p=>!same(p)):[...favorites.slice(-29),{...location,name:placeName||''}];save();}
 async function compareModels(){const token=++compareRequest;compareBusy=true;comparisonErrors=[];const loc={...location};const source=model;const results=await Promise.allSettled(Object.keys(MODELS).filter(m=>m!==source).map(async m=>({m,data:await load(m,loc)})));if(token!==compareRequest)return;comparisons=results.filter(r=>r.status==='fulfilled').map(r=>r.value.data);comparisonErrors=results.flatMap((r,i)=>r.status==='rejected'?[`${Object.keys(MODELS).filter(m=>m!==source)[i]}: ${r.reason?.message||'Unavailable'}`]:[]);compareBusy=false;}
 function download(){if(!data)return;const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),location,selectedTime:new Date(valid).toISOString(),requestedModel:model,forecast:data.raw},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='weatherscope-forecast.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const show=(key,t=valid)=>format(value(data,key,t),describe(key).unit,prefs);
 function profilePath(key){let path='',drawing=false;for(const level of profile){const v=value(data,`${key}-${level}h`,valid);if(!finite(v)){drawing=false;continue;}const x=44+((v-273.15+80)/120)*356,y=20+Math.log(level/100)/Math.log(10)*180;path+=`${drawing?'L':'M'}${x},${y} `;drawing=true;}return path;}
</script>

<section class="weatherscope aurora" aria-label="WeatherScope meteorological dashboard">
 <header><div class="brand"><span class="mark">◉</span><div><h1>WeatherScope<span>FORECAST DESK</span></h1><p>Every detail. One clear forecast.</p></div></div><button class="icon" aria-label="Settings" title="Settings" on:click={()=>settings=!settings}>⚙</button></header>
 {#if demo}<div class="notice">DESIGN PREVIEW · Synthetic sample data, not a weather forecast</div>{/if}
 <div class="location"><div><small>YOUR FORECAST POINT</small>{#if placeName}<h2>{placeName}</h2>{/if}<strong>{location?`${location.lat.toFixed(3)}°, ${location.lon.toFixed(3)}°`:'Click a location on Windy'}</strong></div><button on:click={favorite} disabled={!location} title="Save or remove favorite" aria-pressed={isFavorite} class:saved={isFavorite}>{isFavorite?'★ Saved':'☆ Save point'}</button></div>
 {#if favorites.length}<div class="favorites">{#each favorites as place}<button on:click={()=>onLocation({lat:place.lat,lon:place.lon})}>{place.name||`${place.lat.toFixed(2)}, ${place.lon.toFixed(2)}`}</button>{/each}</div>{/if}
 <div class="source">{#if view==='Winter'}<small>Winter source: ECMWF</small>{:else}<label>Baseline <select aria-label="Baseline model" bind:value={model} on:change={save}>{#each Object.entries(MODELS) as [key,label]}<option value={key}>{label}{key==='mblue'?' · default':''}</option>{/each}</select></label>{/if}<button on:click={()=>refresh(location,model,true)} disabled={busy||!location||view==='Winter'}>↻ Refresh</button><button aria-expanded={detailsOpen} on:click={()=>detailsOpen=!detailsOpen}>Details {detailsOpen?'−':'+'}</button></div>
 {#if settings}<div class="settings"><h2>Display preferences</h2><label>Winter units <select bind:value={prefs.winterUnits} on:change={save}><option value="metric">Metric (m, cm)</option><option value="imperial">Imperial (ft, in)</option></select></label><label>Temperature <select bind:value={prefs.temp} on:change={save}><option value="C">°C</option><option value="F">°F</option></select></label><label>Wind <select bind:value={prefs.wind} on:change={save}><option value="kt">Knots</option><option value="ms">m/s</option></select></label><label><input type="checkbox" bind:checked={prefs.local} on:change={save}/> Use this device’s timezone</label><label>Gust signal (m/s) <input type="number" min="1" max="100" bind:value={thresholds.gust} on:change={save}/></label><label>Wet interval (mm/step) <input type="number" min="0.1" max="100" step="0.1" bind:value={thresholds.rain} on:change={save}/></label></div>{/if}
 {#if view!=='Brief'}<div class="workspace-actions"><button on:click={()=>switchView('Brief')}>← Briefing</button></div>{/if}
 {#if detailsOpen}<div class="detail-menu" aria-label="Advanced tools"><label>Open <select aria-label="Advanced view" value={view==='Brief'?'':view} on:change={e=>switchView(e.currentTarget.value)}><option value="" disabled>Choose a tool</option>{#each ['Explore','Winter','Profile','Compare','Parameters','Coverage'] as name}<option value={name}>{name==='Explore'?'Visual explorer':name==='Profile'?'Atmospheric profile':name==='Compare'?'Compare models':name==='Coverage'?'Data coverage':name}</option>{/each}</select></label></div>{/if}
 {#if view==='Winter'}{#if winterComponent}<svelte:component this={winterComponent} {location} {placeName} units={prefs.winterUnits}/>{:else}<div class="empty"><h2>Wintry Forecast</h2><p>Integrated ECMWF snowline, precipitation type, estimated new snow, 144-hour forecast, sounding and optional map contours. Open the live Windy plugin to use these tools.</p></div>{/if}
 {:else if busy}<div class="empty" role="status"><span class="pulse"></span><h2>Reading the atmosphere</h2><p>Loading {MODELS[model]} forecast and profile fields…</p></div>
 {:else if error}<div class="empty error" role="alert"><h2>Forecast unavailable</h2><p>{error}</p><button on:click={()=>refresh(location,model,true)}>Try again</button><p>No other model has been substituted.</p></div>
 {:else if data}
 {#if view==='Brief'}<SevenDays {data} {prefs} {valid} onTime={chooseTime}/>{/if}
 <div class="timebar"><div><small>VALID TIME · {prefs.local?'DEVICE LOCAL':'UTC'}</small><strong>{timeLabel(valid,prefs.local)}</strong></div><div class="shortcuts">{#each [0,6,12,24] as h}<button on:click={()=>shortcut(h)}>{h?'+'+h+'h':'Now'}</button>{/each}</div></div>
 {#if index<0}<div class="notice">Selected time is outside the returned forecast range. Choose a time below.</div>{/if}
 <label class="time-slider"><span>Explore forecast</span><span>Drag to change time</span><input aria-label="Forecast time" type="range" min="0" max={data.ts.length-1} value={Math.max(0,index)} on:input={e=>chooseTime(data.ts[Number(e.currentTarget.value)])}/></label>
 <details class="source-details"><summary>{served} · {health.age===null?'Run time unavailable':health.age<0?'Check provider run time':'Run '+Math.round(health.age)+'h ago'}</summary><p>{health.available}/{health.total} numeric fields available at this time. {health.lead===null?'Forecast lead unavailable.':'Forecast lead '+Math.round(health.lead)+'h.'}</p><p>{Number.isFinite(Date.parse(data.header.refTime))?'Provider run: '+timeLabel(Date.parse(data.header.refTime),false)+' UTC':'Provider run timestamp missing or invalid'}</p></details>
 {#if mapModel&&mapModel!==data.model}<p class="footnote">Panel: {served} · Windy map: {MODELS[mapModel]||mapModel}. These sources are separate.</p>{/if}
 {#if data.model!==model}<div class="notice">Requested {MODELS[model]}; provider returned {served}.</div>{/if}
 {#if data.header.merged}<div class="notice">Provider reports merged data: {data.header.merged.mergedModelName} from {data.header.merged.mergedModelStart}.</div>{/if}
 {#if view==='Brief'}
 <Brief {data} {valid} {prefs} {thresholds} onTime={chooseTime} onWinter={()=>{detailsOpen=true;switchView('Winter');}}/>
 <Meteorology {data} {valid} {prefs} {comparisons} {comparisonErrors} {compareBusy} onCompare={compareModels}/>
 {:else if view==='Explore'}
 <Explorer {fields} {valid} {prefs} terrain={data.header.modelElevation} onTime={chooseTime}/>
 {:else if view==='Profile'}
 <div class="diagnostics">{#each extra.filter(f=>f.group==='Profile diagnostics') as f}<button on:click={()=>inspect(f.key)} title={f.method}><small>{f.label}</small><strong>{format(at(f,valid),f.unit,prefs)}</strong><small>Calculated · {served}</small></button>{/each}</div>
 <div class="section-title"><h2>Vertical structure</h2><small>{served} · selected forecast time</small></div>
 {#if profile.length}<div class="profile"><svg viewBox="0 0 440 225" role="img" aria-label="Temperature and dew point versus pressure; not a Skew-T diagram"><rect x="44" y="20" width="356" height="180" fill="#0b1825"/>{#each [1000,850,700,500,300,200,100] as p}<line x1="44" x2="400" y1={20+Math.log(p/100)/Math.log(10)*180} y2={20+Math.log(p/100)/Math.log(10)*180} stroke="#253747"/><text x="4" y={24+Math.log(p/100)/Math.log(10)*180}>{p}</text>{/each}{#each [-80,-60,-40,-20,0,20,40] as t}<line x1={44+(t+80)/120*356} x2={44+(t+80)/120*356} y1="20" y2="200" stroke="#253747"/><text x={37+(t+80)/120*356} y="219">{t}</text>{/each}<path d={profilePath('temp')} fill="none" stroke="#f4ba77" stroke-width="2.5"/><path d={profilePath('dewPoint')} fill="none" stroke="#57d8be" stroke-width="2.5"/></svg><p><span class="amber">Temperature</span> / <span class="mint">Dew point</span> · °C vs log pressure (hPa)</p></div><div class="scroll-table"><table><thead><tr><th>hPa</th><th>T</th><th>Td</th><th>RH</th><th>Wind</th><th>Direction</th><th>Height</th></tr></thead><tbody>{#each profile as p}<tr><th>{p}</th>{#each [`temp-${p}h`,`dewPoint-${p}h`,`rh-${p}h`,`wind-${p}h`,`windDir-${p}h`,`gh-${p}h`] as key}<td>{show(key)}</td>{/each}</tr>{/each}</tbody></table></div><p class="footnote">Raw model levels; below-ground levels may be present. No parcel ascent or severe-weather indices are inferred from this chart.</p>{:else}<div class="empty">This source did not return a temperature profile. Try another baseline explicitly.</div>{/if}
 {#if hodo.length>=2}<div class="section-title"><h2>Wind hodograph</h2><small>u / v · m/s · above model terrain</small></div><svg class="hodograph" viewBox="0 0 240 240" role="img" aria-label="Wind hodograph in metres per second"><line x1="20" y1="120" x2="220" y2="120" stroke="#405363"/><line x1="120" y1="20" x2="120" y2="220" stroke="#405363"/>{#each [0.25,0.5,0.75,1] as r}<circle cx="120" cy="120" r={r*100} fill="none" stroke="#293a48"/><text x="123" y={120-r*100+10}>{Math.round(hodoScale*r)}</text>{/each}<polyline points={hodo.map(p=>[120+p.u/hodoScale*100,120-p.v/hodoScale*100].join(',')).join(' ')} fill="none" stroke="#69ddc3" stroke-width="2"/>{#each hodo as p}<circle cx={120+p.u/hodoScale*100} cy={120-p.v/hodoScale*100} r="2" fill="#f4ba77"><title>{p.p} hPa: {p.wind} m/s from {p.dir}°</title></circle>{/each}</svg>{/if}
 {:else if view==='Compare'}
 <div class="section-title"><h2>Model comparison</h2><button disabled={compareBusy} on:click={compareModels}>{compareBusy?'Loading…':'Load comparisons'}</button></div><p class="footnote">Same location and exact valid time. Spread describes disagreement, not forecast probability. Meteoblue may incorporate the other models, so these are not independent ensemble members.</p>
 {#each ['temperature','wind','windGust','pressure'] as key}{@const c=compare([data,...comparisons],key,valid)}<div class="comparison"><strong>{describe(key).label}</strong><div>{#each c.entries as e}<span><small>{MODELS[e.model]||e.model}</small>{format(e.value,describe(key).unit,prefs)}</span>{/each}</div><small>{c.entries.length<2?'At least two matching forecasts needed':`Range across ${c.entries.length} sources: ${format(Math.min(...c.entries.map(e=>e.value)),describe(key).unit,prefs)} – ${format(Math.max(...c.entries.map(e=>e.value)),describe(key).unit,prefs)}`}</small></div>{/each}
 {#each comparisonErrors as err}<p class="notice">{err}</p>{/each}
 {:else if view==='Parameters'}
 <div class="filters"><input type="search" aria-label="Search parameters" placeholder="Search any parameter or pressure level…" bind:value={search}/><select aria-label="Parameter group" bind:value={group}>{#each groups as g}<option>{g}</option>{/each}</select></div>
 <div class="section-title"><h2>{filtered.length} fields</h2><button on:click={download}>Export raw JSON ↓</button></div>
 {#if selectedField}<div class="detail"><button class="close" aria-label="Close field details" on:click={()=>selected=null}>×</button><h2>{selectedField.label}</h2><p>{selectedField.id} · {served}</p><p>{selectedField.method||`Provider unit: ${selectedField.unit}. No invented value is used for missing data.`}</p><p>Sample time: {nearestIndex(selectedField.ts,valid,0)>=0?timeLabel(selectedField.ts[nearestIndex(selectedField.ts,valid,0)],prefs.local):'No matching time'} · {selectedField.ts.length} samples</p></div>{/if}
 <div class="parameter-list">{#each filtered as f}<div class="parameter"><button class="field" on:click={()=>selected=f.id}><span>{f.label}<small>{f.section} · {f.key}</small></span><strong>{format(at(f,valid),f.unit,prefs)}</strong></button><button class:pinned={pins.includes(f.key)} title="Pin or unpin parameter" aria-label={`Pin ${f.label}`} on:click={()=>pin(f.key)}>{pins.includes(f.key)?'★':'☆'}</button></div>{/each}</div>
 {:else if view==='Coverage'}
 <div class="section-title"><h2>What this source supplies</h2><small>{served} · selected time</small></div><p class="footnote">Returned data is checked at runtime. Additional returned variables remain accessible in Parameters, even if their meaning or units are not yet mapped.</p>
 {#each coverage as row}<div class="coverage"><span class:available={row.available}>{row.available?'✓':'—'}</span><div><strong>{row.label}</strong><small>{row.available?'Returned · '+row.note:row.key?'Not supplied at this time · '+row.note:row.note}</small></div></div>{/each}
 <details><summary>Source metadata & daily summaries</summary><pre>{JSON.stringify({header:data.header,summary:data.summary,celestial:data.raw.celestial},null,2)}</pre></details>
 {/if}
 <footer><span>METEOROLOGICAL WORKSPACE</span><span>WeatherScope 0.5 · {demo?'Preview':'Windy'}</span></footer>
 {:else}<div class="empty"><h2>Select a location</h2><p>Click the map to load a Meteoblue briefing.</p></div>{/if}
</section>

<style>

.weatherscope{--bg:#0d1b27;--panel:#152b37;--line:#36505e;--muted:#b2c7d1;--mint:#7be4ca;--ink:#edf7fa;--aurora-hero:linear-gradient(125deg,#193e43,#183044);background:var(--bg);color:var(--ink);font:14px/1.5 system-ui,sans-serif;padding:20px;max-width:780px;margin:auto;min-height:100%;color-scheme:dark;box-sizing:border-box}.weatherscope *{box-sizing:border-box}h1,h2,p{margin:0}h1{font-size:25px;font-weight:600;letter-spacing:-.8px}h1 span{display:block;color:var(--mint);font-size:10px;letter-spacing:1.4px;margin-top:3px}h2{font-size:17px;font-weight:500;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:14px}.brand{display:flex;align-items:center;gap:10px}.brand p{display:none}.mark{display:grid;place-items:center;width:39px;height:39px;background:#193e43;color:var(--mint);border-radius:12px;font-size:29px}button,input,select{font:inherit;background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:9px;min-height:40px;padding:8px 10px;max-width:100%}button{cursor:pointer}button:hover{background:#264451}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--mint);outline-offset:2px}button:disabled{opacity:.5;cursor:wait}.icon{border:0;background:transparent;font-size:20px}.location{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:16px 0}.location h2{font-size:22px;margin:4px 0}.location small{display:none}.location strong{font-size:12px;font-weight:400;color:var(--muted)}.location button{font-size:12px}.saved,.pinned{color:var(--mint)}small{font-size:11px;color:var(--muted)}.source{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:12px 0}.source label{font-size:12px;color:var(--muted)}.source select{color:var(--mint);font-size:12px;margin-left:6px;max-width:170px}.source>button{font-size:12px}.workspace-actions{display:flex;justify-content:flex-end;gap:8px;margin:10px 0}.workspace-actions button{font-size:12px}.detail-menu{padding:12px;background:var(--panel);border-radius:10px;margin:10px 0}.detail-menu label{display:flex;gap:12px;align-items:center}.detail-menu select{flex:1}.timebar{display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap}.timebar small{font-size:10px}.timebar strong{display:block;font-size:18px;font-weight:500}.shortcuts{display:flex;gap:4px}.shortcuts button{font-size:11px;padding:5px 7px;min-height:34px}.time-slider{display:flex;flex-wrap:wrap;justify-content:space-between;margin:10px 0;color:var(--muted);font-size:11px}.time-slider input{width:100%;padding:0;accent-color:var(--mint);min-height:28px}.source-details{font-size:11px;margin:6px 0;color:var(--muted)}summary{cursor:pointer}details p{margin:8px 0}.footnote{font-size:11px;color:var(--muted);line-height:1.6;margin:10px 0}.notice{font-size:11px;border:1px solid #67512c;background:#302b21;color:#eed4a4;padding:8px 10px;border-radius:8px;margin:10px 0}.settings{display:grid;gap:12px;background:var(--panel);border-radius:12px;padding:14px;margin:12px 0}.settings label{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px}.settings input[type=number]{width:80px}.settings input[type=checkbox]{min-height:auto}.favorites{display:flex;flex-wrap:wrap;gap:6px}.favorites button{font-size:12px}.empty{text-align:center;color:var(--muted);padding:40px 10px}.empty h2{margin:12px}.empty button{margin:14px}.error{color:#efb3a4}.pulse{display:inline-block;border:2px solid var(--mint);border-radius:50%;width:16px;height:16px}.section-title{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:20px 0 10px}.diagnostics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:16px 0}.diagnostics button{text-align:left;padding:12px}.diagnostics small,.diagnostics strong{display:block}.diagnostics strong{font-size:19px;font-weight:500;margin:7px 0}.profile,.comparison,.detail{pad